// reusable focus, no library:
final case class Lens[S, A](get: S => A, set: (S, A) => S) {
  def andThen[B](inner: Lens[A, B]): Lens[S, B] =
    Lens(s => inner.get(get(s)), (s, b) => set(s, inner.set(get(s), b)))
}

